shaderSource:
uniform float2 resolution;
uniform float2 touch;
uniform float time;

half4 main(float2 xy) {
  float2 uv = xy / max(resolution, float2(1.0, 1.0));
  float aspect = resolution.x / max(resolution.y, 1.0);
  float2 t = touch / max(resolution, float2(1.0, 1.0));

  float2 p = (uv - 0.5) * float2(aspect, 1.0);
  float2 halfBox = float2(0.5 * aspect, 0.5);
  float2 q = abs(p) - halfBox + 0.12;
  float dist = min(max(q.x, q.y), 0.0) + length(max(q, float2(0.0, 0.0))) - 0.12;
  float edge = smoothstep(-0.22, 0.0, dist);

  float2 normal = normalize(p + float2(0.0001, 0.0001));
  float fringe = edge * 0.55;
  half3 aberr = half3(
    0.55 + fringe * 0.9,
    0.72 + fringe * 0.35,
    1.0
  );

  float2 d = uv - t;
  d.x *= aspect;
  float streak = exp(-pow(d.x * 2.2 + d.y * 0.5, 2.0) * 28.0);
  streak *= exp(-length(d) * 1.5);

  float breath = 0.5 + 0.5 * sin(time * 1.4 + uv.x * 4.0);
  float body = 0.12 + 0.08 * (1.0 - uv.y) + edge * 0.32 + streak * 0.7 + breath * edge * 0.08;
  float2 e = min(uv, 1.0 - uv);
  float inset = smoothstep(0.0, 0.12, min(e.x * aspect, e.y));
  body *= inset;

  half3 tint = mix(half3(0.88, 0.94, 1.0), aberr, edge * 0.85);
  return half4(tint, clamp(body, 0.0, 0.88));
}
